function notice(message){const el=$('#toast');el.textContent=message;if(!el.matches(':popover-open'))el.showPopover();clearTimeout(notice.timer);notice.timer=setTimeout(()=>{if(el.matches(':popover-open'))el.hidePopover();},3500);}
function openInbox(id){if(windowMode==='canvas'){showPeer('tasks',id);return;}if(id)state.active=id;render();if(!$('#inbox').open){windowMode==='tasks'?$('#inbox').show():$('#inbox').showModal();}(active()?$('[data-testid="thread-input"]'):$('[data-testid="new-input"]'))?.focus({preventScroll:true});}
function hideInbox(){if(windowMode==='tasks'){closeTaskWindow();return;}remember();closeMenu(false);$('#inbox').close();renderCanvas();$('[data-action="open-inbox"]')?.focus({preventScroll:true});}
function openWork(id){remember();if(!state.active)state.leftScroll=0;state.active=id;byId(id).unread=false;render();$('[data-testid="thread-input"]')?.focus({preventScroll:true});}
function closeThread(){remember();state.active=null;state.leftScroll=0;render();$('[data-testid="new-input"]')?.focus({preventScroll:true});}
function openMenu(kind,trigger){closeMenu(false);const pos=trigger.getBoundingClientRect();state.menu={kind,query:'',index:-1};const title=kind==='scope'?tr('查看哪些工作','Which work to view'):kind==='recipient'?tr('交给谁处理','Who should handle this'):tr('新工作放在哪个项目','Where this work belongs');
 const el=$('#chooser');el.innerHTML=`<h2 id="chooser-title">${title}</h2><div class="menu-search">${icon('search')}<input data-testid="menu-search" role="combobox" aria-autocomplete="list" aria-controls="menu-options" aria-expanded="true" aria-label="${tr('搜索','Search')}" placeholder="${tr('搜索名称或项目…','Search names or projects…')}"></div><div class="menu-options" id="menu-options" role="listbox"></div><div class="menu-hint">${tr('↑↓ 浏览 · Enter 选择 · Esc 取消','↑↓ to browse · Enter to select · Esc to cancel')}</div>`;
 const left=Math.max(12,Math.min(pos.left,innerWidth-366)),height=Math.min(420,innerHeight-40),top=pos.bottom+9+height<innerHeight?pos.bottom+9:Math.max(12,pos.top-height-9);el.style.left=left+'px';el.style.top=top+'px';el.style.maxHeight=height+'px';renderOptions();el.showPopover();trigger.setAttribute('aria-expanded','true');$('[data-testid="menu-search"]').focus();}
function renderOptions(){const m=state.menu,options=filteredOptions();m.index=Math.min(m.index,options.length-1);$('.menu-options').innerHTML=options.map((o,i)=>`<button type="button" id="menu-option-${i}" class="menu-option ${i===m.index?'browsing':''}" role="option" aria-selected="${selectedOption(m.kind)===o.id}" data-choice="${o.id}" tabindex="-1">${o.agent?avatar(o.agent):o.type==='norma'?orb:icon(o.type==='project'?'folder':'grid')}<div><strong>${esc(l(o.title))}</strong><small>${esc(l(o.detail))}</small></div>${selectedOption(m.kind)===o.id?icon('check').replace('<svg ','<svg class="selected-check" '):''}</button>`).join('')||`<p class="menu-empty">${tr('没有找到匹配项','No matching options')}</p>`;const input=$('[data-testid="menu-search"]');if(m.index>=0){input.setAttribute('aria-activedescendant','menu-option-'+m.index);$('#menu-option-'+m.index)?.scrollIntoView({block:'nearest'});}else input.removeAttribute('aria-activedescendant');}
function closeMenu(focus=true){const m=state.menu;if($('#chooser').matches(':popover-open'))$('#chooser').hidePopover();state.menu=null;if(m){const trigger=$(`[data-menu="${m.kind}"]`);trigger?.setAttribute('aria-expanded','false');if(focus)trigger?.focus({preventScroll:true});}}
function chooseOption(id){const kind=state.menu.kind,o=menuOptions(kind).find(o=>o.id===id);if(!o)return;remember();if(kind==='recipient')state.recipient=id;else{state[kind]={space:o.space,project:o.project};if(kind==='scope')state.leftScroll=0;}closeMenu(false);render();$(`[data-menu="${kind}"]`)?.focus({preventScroll:true});}
function createWork(){const text=state.newDraft.trim();if(!text)return;remember();const target=receiver();if(target){sendMessage(target,text);state.newDraft='';openWork(target.id);return;}const dest=state.destination,id=windowMode==='embedded'?'new-'+(++state.next):'new-'+crypto.randomUUID();const a={id,space:dest.space,project:dest.project,card:null,session:'planning-'+id,agent:'Norma',engine:['协调者','Coordinator'],color:'#c4a6dc',status:'planning',progress:0,total:3,archived:false,title:[text,text],summary:['目标已记录，等待拆解','Goal recorded, awaiting planning'],initial:[text,text],answer:['已把这项工作放进指定项目。下一步是明确范围、拆解任务，再交给合适的 Agent。这里先保留独立讨论，尚未创建执行卡片。','The work is in the selected project. Next comes scope, planning and agent assignment. This discussion is separate; no execution card exists yet.'],steps:[['明确目标与约束','Clarify goals and constraints'],['拆解并安排 Agent','Plan and assign agents'],['跟进结果与待决定事项','Track results and decisions']]};state.items.unshift(a);state.newDraft='';state.active=id;ctx(a).scroll=0;render();$('[data-testid="thread-input"]')?.focus({preventScroll:true});notice(tr('已记录新工作 · 等待 Norma 拆解','Work recorded · Awaiting Norma’s plan'));}
function accept(){const a=active();if(!a||a.status!=='needs')return;remember();a.status=a.id==='navigation'?'merge':'running';a.summary=a.id==='navigation'?['验收已记录，等待合并','Review recorded, awaiting merge']:['方案已确认，继续执行','Plan confirmed, continuing'];const c=ctx(a);c.messages.push({role:'user',text:l(a.recommendation)},{role:'assistant',sample:true,text:a.id==='navigation'?['验收结果已记录，保留待合并状态。','Review recorded. The work remains awaiting merge.']:['方向已记录，后续进展仍留在这张原卡片中。','Direction recorded. Further progress stays in the original card.']});c.scroll=Infinity;render();notice(a.id==='navigation'?tr('已验收，尚未合并','Reviewed; not merged'):tr('已记录，工作继续推进','Recorded; work continues'));}
function simulate(){if(state.eventAdded){notice(tr('这条示例进展已经送达','This sample update has already arrived'));return;}remember();state.eventAdded=true;const a=byId('drawer');a.status='done';a.progress=a.total;a.unread=state.active!==a.id;a.summary=['交互检查已完成，等待你查看','Interaction checks complete; ready to view'];a.answer=['任务页的快捷键、工作空间筛选和原卡片会话衔接已整理好。你可以打开页面检查两种状态，再决定是否继续推进实现。','The task page shortcut, workspace filtering and original card conversations are ready to inspect. Review both states before continuing implementation.'];render();notice(tr('Kevin 有了新答案，当前对话已保留','Kevin has an answer. Your current conversation stays open.'));}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.menu){openMenu(b.dataset.menu,b);return;}if(b.dataset.choice){chooseOption(b.dataset.choice);return;}if(b.dataset.work){openWork(b.dataset.work);return;}if(b.dataset.canvasChat){openInbox(b.dataset.canvasChat);return;}
 const a=b.dataset.action;if(!a)return;if(a==='open-inbox'||a==='return-inbox')openInbox();if(a==='hide-inbox')hideInbox();if(a==='open-canvas')showPeer('canvas');if(a==='close-thread')closeThread();if(a==='locate')locate();if(a==='accept')accept();if(a==='simulate')simulate();
 if(a==='language'){remember();lang=lang==='zh'?'en':'zh';render();}
 if(a==='toggle-archive'){remember();state.archiveOpen=!state.archiveOpen;render();}
 if(a==='archive'&&active()?.status==='done'){remember();active().archived=!active().archived;if(active().archived)state.archiveOpen=true;render();}
 if(a==='edit-recommendation'){const w=active();ctx(w).draft=l(w.recommendation);render();$('[data-testid="thread-input"]').focus();}
 if(a==='search'){remember();state.searchOpen=!state.searchOpen;render();$('[data-testid="task-search"]')?.focus();}
 if(a==='clear-search'){remember();state.searchOpen=false;state.search='';render();$('[data-action="search"]').focus();}
 if(a==='clear-filters'||a==='show-current'){remember();state.scope={space:'all',project:'all'};state.search='';render();}
 if(a==='attach')$('#attachment-input').click();if(a==='remove-attachment'){ctx(active()).attachment=null;render();}
 if(a==='video'){const v=$('#wallpaper');v.paused?v.play().catch(()=>notice(tr('背景视频暂时无法播放','The background video could not play'))):v.pause();}
 if(a==='fit-canvas'){state.canvasId=null;state.camera={x:50,y:50,z:Math.min(.8,(innerWidth-100)/1470)};renderCanvas();}
});
document.addEventListener('input',e=>{const test=e.target.dataset.testid;if(test==='new-input'){state.newDraft=e.target.value;$('[data-testid="new-send"]').disabled=!state.newDraft.trim();}if(test==='thread-input'){ctx(active()).draft=e.target.value;$('[data-testid="thread-send"]').disabled=!e.target.value.trim();}if(test==='canvas-input'){ctx(byId(state.canvasId)).draft=e.target.value;$('[data-testid="canvas-send"]').disabled=!e.target.value.trim();}if(test==='menu-search'){state.menu.query=e.target.value;state.menu.index=-1;renderOptions();}if(test==='task-search'){remember();state.search=e.target.value;render();}});
document.addEventListener('change',e=>{if(e.target.id==='attachment-input'&&e.target.files[0]){const f=e.target.files[0];ctx(active()).attachment={name:f.name,size:f.size};remember();render();notice(tr('已添加本地附件名称 · 原型不上传文件','Local filename attached · This prototype does not upload files'));}});
document.addEventListener('submit',e=>{if(!e.target.dataset.form)return;e.preventDefault();const form=e.target.dataset.form;if(form==='new'){createWork();return;}const a=form==='canvas'?byId(state.canvasId):active(),c=ctx(a);if(!c.draft.trim())return;remember();sendMessage(a,c.draft);render();if(form==='canvas'){$('[data-testid="canvas-input"]').focus({preventScroll:true});$('.canvas-card.focused .canvas-terminal').scrollTop=1e6;}else $('[data-testid="thread-input"]').focus({preventScroll:true});});
document.addEventListener('keydown',e=>{if(e.isComposing)return;
 if((e.metaKey||e.ctrlKey)&&e.shiftKey&&e.code==='Space'){e.preventDefault();$('#inbox').open?hideInbox():openInbox();return;}
 if(state.menu&&$('#chooser').matches(':popover-open')){if(e.key==='Escape'||e.key==='Tab'){if(e.key==='Escape')e.preventDefault();e.stopPropagation();closeMenu();return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const n=filteredOptions().length;if(n){state.menu.index=(state.menu.index+(e.key==='ArrowDown'?1:-1)+n)%n;renderOptions();}return;}if(e.key==='Enter'){e.preventDefault();const option=filteredOptions()[state.menu.index<0?0:state.menu.index];if(option)chooseOption(option.id);return;}}
 if(e.key==='Escape'&&$('#inbox').open){e.preventDefault();state.active?closeThread():hideInbox();return;}
 if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&e.target.closest('form')){e.preventDefault();e.target.closest('form').requestSubmit();}
});
$('#inbox').addEventListener('cancel',e=>{e.preventDefault();state.active?closeThread():hideInbox();});
$('#chooser').addEventListener('toggle',e=>{if(e.newState==='closed'&&!$('#chooser').matches(':popover-open')&&state.menu){const kind=state.menu.kind;state.menu=null;$(`[data-menu="${kind}"]`)?.setAttribute('aria-expanded','false');}});
const reduce=matchMedia('(prefers-reduced-motion: reduce)');const syncReduce=()=>{if(reduce.matches)$('#wallpaper').pause();};reduce.addEventListener('change',syncReduce);syncReduce();
const videoState=()=>{const b=$('[data-action="video"]');if(b){b.innerHTML=icon($('#wallpaper').paused?'play':'pause');b.setAttribute('aria-pressed',String(!$('#wallpaper').paused));}};$('#wallpaper').addEventListener('play',videoState);$('#wallpaper').addEventListener('pause',videoState);
initSharedWindows();const params=new URLSearchParams(location.search);if(byId(params.get('task')))state.active=params.get('task');render();initCanvas();if(windowMode==='canvas'){if(state.active)focusCanvasCard(state.active);}else if(params.get('scene')!=='canvas'){openInbox();}if(windowMode==='tasks')$('#wallpaper').pause();
